// Read transcript from the binary reader node
const transcript = $('Read Transcript Binary').first().json.transcript || '';
const sessionContext = $('Read Transcript Binary').first().json.sessionContext || 'None provided';

// Get all Notion KB items from the merge node
const items = $input.all();

// Extract brand voice pages
const brandVoice = items
  .filter(i => i.json.properties?.Type?.select?.name === 'Brand Voice')
  .map(i => i.json.properties?.Content?.rich_text?.map(t => t.plain_text).join('') || '')
  .join('\n\n');

// Extract example posts
const examplePosts = items
  .filter(i => i.json.properties?.Type?.select?.name === 'Example Post')
  .map((i, idx) => {
    const content = i.json.properties?.Content?.rich_text?.map(t => t.plain_text).join('') || '';
    const name = i.json.properties?.Name?.title?.map(t => t.plain_text).join('') || `Post ${idx + 1}`;
    return `--- Example Post ${idx + 1}: ${name} ---\n${content}`;
  })
  .join('\n\n');

// Extract coaching frameworks
const frameworks = items
  .filter(i => i.json.properties?.Type?.select?.name === 'Framework')
  .map(i => {
    const name = i.json.properties?.Name?.title?.map(t => t.plain_text).join('') || '';
    const content = i.json.properties?.Content?.rich_text?.map(t => t.plain_text).join('') || '';
    return `- ${name}: ${content}`;
  })
  .join('\n');

return [{
  json: {
    transcript,
    sessionContext,
    brandVoice: brandVoice || 'Active voice. Direct. Practitioner-level. No hype, no exclamation marks. Short sentences. Second person where possible. No motivational filler.',
    examplePosts: examplePosts || 'No example posts found in knowledge base.',
    frameworks: frameworks || 'No frameworks found in knowledge base.',
    icp: 'Tech startup founders and early-stage CEOs (Seed to Series B). They are time-poor, results-oriented, skeptical of generic advice. They respond to specific, contrarian, practitioner-grounded insights.'
  }
}];

// Parse topic extraction result and format for human review
const response = $input.first().json;

// Handle both raw JSON and message-wrapped responses
let content;
if (response.message && response.message.content) {
  content = typeof response.message.content === 'string' ? JSON.parse(response.message.content) : response.message.content;
} else if (response.topics) {
  content = response;
} else if (typeof response === 'string') {
  content = JSON.parse(response);
} else {
  content = response;
}

const topics = content.topics || [];

// Format a clean markdown summary for the human review form
const summary = topics.map(t => `**Topic ${t.id}: ${t.title}**\n- Insight: ${t.insight}\n- Hook angle: ${t.hook_angle}\n- ICP relevance: ${t.icp_relevance}\n- Why aha: ${t.why_aha}`).join('\n\n');

return [{
  json: {
    topics,
    summary,
    topicChoices: topics.map(t => `${t.id} — ${t.title}`),
    context: $('Build Knowledge Context').first().json
  }
}];

// Attach the brief back to the item so the next node can use both topic + brief + context
const response = $input.first().json;
let brief;
if (response.message && response.message.content) {
  brief = typeof response.message.content === 'string' ? JSON.parse(response.message.content) : response.message.content;
} else {
  brief = response;
}

return [{
  json: {
    ...$('Parse Topics').item.json,
    brief
  }
}];

