// Pull post text out of OpenAI response and compute metadata for Notion
const response = $input.first().json;
const postText = response.message?.content || response.content || response.text || '';

const wordCount = postText.trim().split(/\s+/).length;
const charCount = postText.length;
const readTimeSec = Math.ceil(wordCount / 3.5); // ~210 wpm reading speed

const topicData = $('Attach Brief').item.json;

return [{
  json: {
    postText,
    wordCount,
    charCount,
    readTimeSec,
    topic: topicData.topic,
    brief: topicData.brief,
    customAngle: topicData.customAngle,
    runTimestamp: topicData.runTimestamp
  }
}];

// Summarise the 3 drafts for the Slack notification
const items = $input.all();
const count = items.length;
const titles = items.map((i, idx) => `${idx + 1}. ${i.json.topic?.title || i.json.title || 'Untitled'}`).join('\n');

return [{
  json: {
    count,
    titles,
    summary: `🎯 ${count} new LinkedIn drafts ready for review in Notion → Content Calendar (filter: Status = "Draft for Review")`
  }
}];

